using System; using System.Collections.Generic; using System.Linq; using KingmakerMountedCombat.Diagnostics;
namespace KingmakerMountedCombat.Tests
{
 internal static class OwnedPairsAuthorityTests
 {
  const string Anchor="11111111-1111-4111-8111-111111111111",Campaign="22222222-1111-4111-8111-111111111111",Area="0123456789abcdef0123456789abcdef",OtherArea="fedcba9876543210fedcba9876543210";
  static int Main()
  {
   var t=new TestRunner();
   foreach(var selectedCase in new[]{"exploration","combat-rider-first","combat-mount-first","realtime-core","realtime-casting","realtime-charge","native-life-cleanup"}) t.Run("closed inherited native read-only case "+selectedCase,()=>{var f=new Fixture();f.Request.OwnedPairs.Case=selectedCase;f.Request.PersistenceCase=null;f.Request.OwnedPairs.ExpectedNativeWriteCount=0;Valid(f.Request);var a=f.Scope();TestRunner.True(a.MatchesOwnedPairsPlan(true,true),"Exact read-only plan missing.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Load,f.Root)==null,"Sole inherited native load refused.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,f.Write(9),f.Root)!=null,"Read-only native campaign gained a write.");TestRunner.Equal(0,a.OwnedPairsReservationCount,"Read-only plan gained a reservation.");TestRunner.Equal(0,a.AdmittedNativeWriteRequests,"Refused write spent authority.");});
   foreach(var checkpoint in new[]{"multi-exploration-manual","multi-exploration-quick","multi-exploration-auto","multi-rt-debt-manual","multi-tb-debt-manual","zero-mounted-tb-retained-manual","legacy-mounted-pending-tb-manual","owned-schema1-manual"})t.Run("source checkpoint exact category and reservation "+checkpoint,()=>{var f=new Fixture();f.Request.PersistenceCase=checkpoint;Valid(f.Request);var a=f.Scope();TestRunner.True(a.ValidateArchiveIdentity(f.Load,f.Root)==null,"Native header enumeration refused.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Load,f.Root)!=null,"Unreserved load admitted.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,f.Write(f.Number),f.Root)!=null,"Early output admitted.");Unspent(a);f.Reserve(a);TestRunner.True(a.MatchesOwnedPairsPlan(true,true),"Atomic two-entry plan missing.");TestRunner.Equal(f.Number,a.OwnedPairsOutputNumber,"Observed native number replaced.");TestRunner.True(ReferenceEquals(f.Descriptor,a.OwnedPairsSourceDescriptor),"Native source reference replaced.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,f.Write(f.Number),f.Root)!=null,"Reserved output admitted before the sole load.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Load,f.Root)==null,"Reserved native load refused.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,f.Write(f.Number),f.Root)==null,"Reserved native write refused.");using(var lease=a.BeginWrite(f.Write(f.Number),f.Root)){BootstrapVirtualFile.OutputExists=true;lease.Complete();}TestRunner.True(a.MatchesOwnedPairsPlan(true,false),"Settled two-entry plan lost.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Load,f.Root)!=null,"Second native load admitted.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,f.Write(f.Number),f.Root)!=null,"Second native write admitted.");Reset();});
   foreach(var mutation in new[]{"missing","wrong-family","wrong-case","write2","load0","same-source","duplicate-role","bad-id","missing-roster","foreign-roster","duplicate-roster","Working","other-source-name","area-route","alternate","source-hash","old-permission","unsupported-checkpoint","checkpoint-on-exploration","cold-no-parent"})t.Run("typed request refuses "+mutation,()=>{var f=new Fixture();var r=f.Request;switch(mutation){case "missing":r.OwnedPairs=null;break;case "wrong-family":r.Scenario="fixture-intake";break;case "wrong-case":r.OwnedPairs.Case="anything";break;case "write2":r.OwnedPairs.ExpectedNativeWriteCount=2;break;case "load0":r.OwnedPairs.ExpectedNativeLoadCount=0;break;case "same-source":r.OwnedPairs.SourceRunId=r.RunId;break;case "duplicate-role":r.OwnedPairs.MountAId=r.OwnedPairs.RiderAId;break;case "bad-id":r.OwnedPairs.RiderAId="actor";break;case "missing-roster":r.OwnedPairs.PartyIds=null;break;case "foreign-roster":r.OwnedPairs.PartyIds=r.OwnedPairs.PartyIds.Skip(1).ToArray();break;case "duplicate-roster":r.OwnedPairs.PartyIds=r.OwnedPairs.PartyIds.Concat(new[]{r.OwnedPairs.RiderAId}).ToArray();break;case "Working":r.PersistenceLoad.GameId=Anchor;break;case "other-source-name":r.PersistenceLoad.InternalName="KMC_AUTOMATION_WORKING";break;case "area-route":r.PersistenceAreaTarget=new RuntimeAreaTransitionTarget();break;case "alternate":r.PersistenceAlternate=r.PersistenceLoad;break;case "source-hash":r.PersistenceLoad.Sha256=new string('e',64);break;case "old-permission":r.ManualDerived=new Chunk7ManualDerivedSelection();break;case "unsupported-checkpoint":r.PersistenceCase="multi-unknown-checkpoint";break;case "checkpoint-on-exploration":r.OwnedPairs.Case="exploration";break;case "cold-no-parent":r.OwnedPairs.Case="persistence-load";break;}TestRunner.True(r.Validate().Count>0,"Foreign typed fixture admitted.");});
   foreach(var fault in new[]{"request","game","manager","descriptor","token","source","type","name","zero","previous-number","foreign-number","inventory","enumeration","bytes","output"}) t.Run("failed atomic output reservation retains no leaf "+fault,()=>{var f=new Fixture();var a=f.Scope();var r=f.Request;var game=f.Game;var manager=f.Manager;var descriptor=f.Descriptor;var target=f.Load;var number=f.Number;var type=f.Type;var name=f.Name;switch(fault){case "request":r=new Fixture().Request;break;case "game":game=new object();break;case "manager":manager=new object();break;case "descriptor":descriptor=null;break;case "token":r.TransactionToken=new string('9',64);break;case "source":target.GameId=Anchor;break;case "type":type="Quick";break;case "name":name="foreign";break;case "zero":number=0;break;case "previous-number":number--;break;case "foreign-number":number++;break;case "inventory":BootstrapVirtualDirectory.ForeignEntry=true;break;case "enumeration":BootstrapVirtualDirectory.Throw=true;break;case "bytes":BootstrapVirtualStorage.SourceChanged=true;break;case "output":BootstrapVirtualFile.OutputExists=true;break;}Refuses(()=>a.ReserveOwnedPairsOutput(r,game,manager,descriptor,target,number,type,name));Reset();Unspent(a);TestRunner.True(a.OwnedPairsOutputLeaf==null&&a.OwnedPairsSourceDescriptor==null,"Failed reservation retained native write permission.");});
   foreach(var delta in new[]{0,1})t.Run("repeat output reservation refuses "+delta,()=>{var f=new Fixture();var a=f.Scope();f.Reserve(a);Refuses(()=>a.ReserveOwnedPairsOutput(f.Request,f.Game,f.Manager,new object(),f.Load,f.Number+delta,f.Type,f.Name));TestRunner.Equal(f.Number,a.OwnedPairsOutputNumber,"Original reservation replaced.");TestRunner.Equal(1,a.OwnedPairsReservationCount,"Duplicate changed reservation count.");TestRunner.Equal(0,a.AdmittedNativeLoadRequests,"Reservation spent load.");TestRunner.Equal(0,a.AdmittedNativeWriteRequests,"Reservation spent write.");});
   foreach(var mutation in new[]{"token","actor","roster","scenario","source-length"}) foreach(var boundary in new[]{"validate-load","authorize-load","archive-identity","authorize-write","storage"}) t.Run("captured request mutation refuses later "+mutation+" "+boundary,()=>{var f=new Fixture();var a=f.Scope();f.Reserve(a);if(boundary=="authorize-write"||boundary=="storage"){TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Load,f.Root)==null,"Setup load failed.");if(boundary=="storage")TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,f.Write(f.Number),f.Root)==null,"Setup write failed.");}var load=f.Load;var write=f.Write(f.Number);var loads=a.AdmittedNativeLoadRequests;var writes=a.AdmittedNativeWriteRequests;switch(mutation){case "token":f.Request.TransactionToken=new string('9',64);break;case "actor":f.Request.OwnedPairs.RiderAId="99999999-1111-4111-8111-111111111111";break;case "roster":Array.Reverse(f.Request.OwnedPairs.PartyIds);break;case "scenario":f.Request.Scenario="fixture-intake";break;case "source-length":f.Request.PersistenceLoad.Length++;break;}if(boundary=="storage")Refuses(()=>{using(a.BeginWrite(write,f.Root)){} });else TestRunner.True((boundary=="validate-load"?a.Validate(RuntimeSaveOperation.Load,load,f.Root):boundary=="archive-identity"?a.ValidateArchiveIdentity(load,f.Root):a.AuthorizeNativeRequest(boundary=="authorize-write"?RuntimeSaveOperation.Write:RuntimeSaveOperation.Load,boundary=="authorize-write"?write:load,f.Root))!=null,"Changed captured request admitted.");TestRunner.True(!a.MatchesOwnedPairsPlan(true,false),"Changed captured request matched plan.");TestRunner.Equal(loads,a.AdmittedNativeLoadRequests,"Refusal spent load.");TestRunner.Equal(writes,a.AdmittedNativeWriteRequests,"Refusal spent write.");TestRunner.Equal(1,a.OwnedPairsReservationCount,"Refusal changed exact reservation.");});
   t.Run("historical authority has no inherited reservation",()=>{var f=new Fixture();var a=f.Scope(false);Refuses(()=>f.Reserve(a));TestRunner.True(a.Validate(RuntimeSaveOperation.Load,f.Load,f.Root)==null,"Historical immutable source admission changed.");});

   foreach(var areas in new[]{false,true})t.Run("closed owned replay immutable load quota "+areas,()=>{var f=Replay(areas);Valid(f.Request);var a=f.Scope();TestRunner.True(a.MatchesOwnedPairsPlan(true,true),"Closed replay source plan missing.");for(var i=0;i<f.Request.OwnedPairs.ExpectedNativeLoadCount;i++){TestRunner.True(a.Validate(RuntimeSaveOperation.Load,f.Load,f.Root)==null,"Selected next load refused.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Load,f.Root)==null,"Selected next actual load refused.");}TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Load,f.Root)!=null,"One extra native load admitted.");TestRunner.Equal(areas?1:3,a.AdmittedNativeLoadRequests,"Refused extra load changed count.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,f.Write(9),f.Root)!=null,"Replay gained a native write.");Unreserved(a);});
   foreach(var areas in new[]{false,true})foreach(var count in new[]{0,1,2,3,4})if(count!=(areas?1:3))t.Run("replay quota mismatch "+areas+" "+count,()=>{var f=Replay(areas);f.Request.OwnedPairs.ExpectedNativeLoadCount=count;TestRunner.True(f.Request.Validate().Count>0,"Declared replay quota expanded or shrank.");Refuses(()=>f.Scope());});
   foreach(var caseName in new[]{"multi-exploration-three-loads-manual","multi-exploration-three-area-transfers-manual"})t.Run("replay source save alias refuses "+caseName,()=>{var f=new Fixture();f.Request.PersistenceCase=caseName;TestRunner.True(f.Request.Validate().Count>0,"Save source gained replay alias.");});
   foreach(var change in new[]{"case","selection","count","route-area","route-entry","route-mode","route-order","route-null","token","actor"})foreach(var boundary in new[]{"validate","admit","identity"})t.Run("closed replay later mutation refuses "+change+" "+boundary,()=>{var f=Replay(true);var a=f.Scope();switch(change){case "case":f.Request.PersistenceCase="multi-exploration-three-loads-manual";f.Request.PersistenceReplayTargets=null;f.Request.OwnedPairs.ExpectedNativeLoadCount=3;break;case "selection":f.Request.OwnedPairs.Case="persistence-save";break;case "count":f.Request.OwnedPairs.ExpectedNativeLoadCount=3;break;case "route-area":f.Request.PersistenceReplayTargets[0].Area=new string('a',32);break;case "route-entry":f.Request.PersistenceReplayTargets[0].EnterPoint=new string('b',32);break;case "route-mode":f.Request.PersistenceReplayTargets[0].AutoSaveMode="BeforeExit";break;case "route-order":Array.Reverse(f.Request.PersistenceReplayTargets);break;case "route-null":f.Request.PersistenceReplayTargets=null;break;case "token":f.Request.TransactionToken=new string('9',64);break;case "actor":f.Request.OwnedPairs.RiderAId="99999999-1111-4111-8111-111111111111";break;}TestRunner.True((boundary=="validate"?a.Validate(RuntimeSaveOperation.Load,f.Load,f.Root):boundary=="identity"?a.ValidateArchiveIdentity(f.Load,f.Root):a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Load,f.Root))!=null,"Changed captured replay admitted.");TestRunner.True(!a.MatchesOwnedPairsPlan(true,false),"Changed replay matched original plan.");TestRunner.Equal(0,a.AdmittedNativeLoadRequests,"Refusal spent native load.");Unreserved(a);});
   foreach(var change in new[]{"same-loaded-area","too-few","null-target","wrong-mode","route-on-loads"})t.Run("owned replay route pre-admission "+change,()=>{var f=Replay(true);switch(change){case "same-loaded-area":f.Request.PersistenceReplayTargets[0].Area=Area;break;case "too-few":f.Request.PersistenceReplayTargets=f.Request.PersistenceReplayTargets.Take(2).ToArray();break;case "null-target":f.Request.PersistenceReplayTargets[0]=null;break;case "wrong-mode":f.Request.PersistenceReplayTargets[0].AutoSaveMode="AfterEntry";break;case "route-on-loads":f.Request.PersistenceCase="multi-exploration-three-loads-manual";f.Request.OwnedPairs.ExpectedNativeLoadCount=3;break;}TestRunner.True(f.Request.Validate().Count>0,"Unqualified route admitted.");});
   t.Run("owned schema1 cold has one exact dynamic resave and immutable derivative",()=>{var f=OwnedSchema1();Valid(f.Request);var a=f.Scope();f.Reserve(a);TestRunner.Equal("Manual_9_KMC_C7_SCHEMA1.zks",a.OwnedPairsOutputLeaf,"Historical output did not use the exact observed next number/name.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Load,f.Root)==null,"Sole historical load refused.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,f.Write(f.Number),f.Root)==null,"Sole resave refused.");using(var lease=a.BeginWrite(f.Write(f.Number),f.Root)){BootstrapVirtualFile.OutputExists=true;lease.Complete();}TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Load,f.Root)!=null,"Second historical load admitted.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,f.Write(f.Number),f.Root)!=null,"Second resave admitted.");Reset();});
   foreach(var mutation in new[]{"missing-receipt","wrong-family","source-alias","legacy-owned","write0","write2","load2"})t.Run("closed owned schema1 request "+mutation,()=>{var f=OwnedSchema1();switch(mutation){case "missing-receipt":f.Request.Schema1DerivationSha256=null;break;case "wrong-family":f.Request.Scenario="chunk7-persistence-load";break;case "source-alias":f.Request.PersistenceCase="owned-schema1-manual";break;case "legacy-owned":f.Request.PersistenceCase="legacy-schema1-resave-manual";break;case "write0":f.Request.OwnedPairs.ExpectedNativeWriteCount=0;break;case "write2":f.Request.OwnedPairs.ExpectedNativeWriteCount=2;break;case "load2":f.Request.OwnedPairs.ExpectedNativeLoadCount=2;break;}TestRunner.True(f.Request.Validate().Count>0,"Invalid historical source admission.");Refuses(()=>f.Scope());});
   foreach(var boundary in new[]{"identity","load","write"})t.Run("captured historical receipt mutation refuses "+boundary,()=>{var f=OwnedSchema1();var a=f.Scope();f.Reserve(a);if(boundary=="write")TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Load,f.Root)==null,"Setup load refused.");f.Request.Schema1DerivationSha256=new string('e',64);var result=boundary=="identity"?a.ValidateArchiveIdentity(f.Load,f.Root):a.AuthorizeNativeRequest(boundary=="write"?RuntimeSaveOperation.Write:RuntimeSaveOperation.Load,boundary=="write"?f.Write(f.Number):f.Load,f.Root);TestRunner.True(result!=null,"Mutable receipt granted historical authority.");TestRunner.Equal(0,a.AdmittedNativeWriteRequests,"Refusal spent a write.");});
   t.Run("source writer cannot carry historical derivation authority",()=>{var f=new Fixture();f.Request.PersistenceCase="owned-schema1-manual";f.Request.Schema1DerivationSha256=new string('a',64);TestRunner.True(f.Request.Validate().Count>0,"Source writer accepted derivative metadata authority.");});
   foreach(var cold in new[]{false,true})t.Run("owned area distinct input and destination "+cold,()=>{var f=AreaCase(cold);Valid(f.Request);var a=f.Scope();if(!cold)f.Reserve(a);TestRunner.True(a.MatchesOwnedPairsPlan(true,true),"Area plan missing.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Load,f.Root)==null,"Exact native area input refused.");var w=f.Write(f.Number);if(cold){TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,w,f.Root)!=null,"Cold area granted a write.");Unreserved(a);}else{var old=f.Write(f.Number);old.Area=Area;TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,old,f.Root)!=null,"Area output admitted in source area.");TestRunner.Equal(0,a.AdmittedNativeWriteRequests,"Wrong area spent write.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,w,f.Root)==null,"Destination Auto refused.");using(var lease=a.BeginWrite(w,f.Root)){BootstrapVirtualFile.OutputExists=true;lease.Complete();}TestRunner.True(a.MatchesOwnedPairsPlan(true,false),"Destination Auto plan changed.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,w,f.Root)!=null,"Second Auto admitted.");}TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Load,f.Root)!=null,"Second area load admitted.");Reset();});
   foreach(var fault in new[]{"missing-source","source-zero","same-area","missing-target","wrong-mode","source-override","cold-input-source","second-owner","write-quota"})t.Run("owned area request refuses "+fault,()=>{var f=AreaCase(fault=="cold-input-source");switch(fault){case "missing-source":f.Request.OwnedPairs.SourceArea=null;break;case "source-zero":f.Request.OwnedPairs.SourceArea=new string('0',32);break;case "same-area":f.Request.PersistenceAreaTarget.Area=Area;break;case "missing-target":f.Request.PersistenceAreaTarget=null;break;case "wrong-mode":f.Request.PersistenceAreaTarget.AutoSaveMode="BeforeExit";break;case "source-override":f.Request.OwnedPairs.SourceArea=new string('e',32);break;case "cold-input-source":f.Request.PersistenceLoad.Area=Area;break;case "second-owner":f.Request.OwnedPairs.RiderBId=f.Request.OwnedPairs.RiderAId;break;case "write-quota":f.Request.OwnedPairs.ExpectedNativeWriteCount=2;break;}TestRunner.True(f.Request.Validate().Count>0,"Forged owned area selection admitted.");Refuses(()=>f.Scope());});
   foreach(var checkpoint in new[]{"multi-exploration-manual","multi-exploration-quick","multi-exploration-auto","multi-exploration-three-loads-manual","multi-exploration-three-area-transfers-manual"})t.Run("SourceArea forbidden on old route "+checkpoint,()=>{var f=checkpoint.Contains("three-")?Replay(checkpoint.Contains("area-transfers")):new Fixture();f.Request.PersistenceCase=checkpoint;f.Request.OwnedPairs.SourceArea=Area;TestRunner.True(f.Request.Validate().Count>0,"SourceArea leaked into another route.");});
   foreach(var mutation in new[]{"source-area","target-area","target-entry","target-mode"})foreach(var boundary in new[]{"validate-load","authorize-load","archive-identity","authorize-write","storage"})t.Run("owned area captured mutation "+mutation+" "+boundary,()=>{var f=AreaCase(false);var a=f.Scope();f.Reserve(a);if(boundary=="authorize-write"||boundary=="storage"){TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Load,f.Root)==null,"Setup load failed.");if(boundary=="storage")TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,f.Write(f.Number),f.Root)==null,"Setup write failed.");}var load=f.Load;var write=f.Write(f.Number);var loads=a.AdmittedNativeLoadRequests;var writes=a.AdmittedNativeWriteRequests;switch(mutation){case "source-area":f.Request.OwnedPairs.SourceArea=new string('e',32);f.Request.PersistenceLoad.Area=f.Request.OwnedPairs.SourceArea;break;case "target-area":f.Request.PersistenceAreaTarget.Area=new string('e',32);break;case "target-entry":f.Request.PersistenceAreaTarget.EnterPoint=new string('f',32);break;case "target-mode":f.Request.PersistenceAreaTarget.AutoSaveMode="None";break;}if(boundary=="storage")Refuses(()=>{using(a.BeginWrite(write,f.Root)){} });else TestRunner.True((boundary=="validate-load"?a.Validate(RuntimeSaveOperation.Load,load,f.Root):boundary=="archive-identity"?a.ValidateArchiveIdentity(load,f.Root):a.AuthorizeNativeRequest(boundary=="authorize-write"?RuntimeSaveOperation.Write:RuntimeSaveOperation.Load,boundary=="authorize-write"?write:load,f.Root))!=null,"Mutated area request admitted.");TestRunner.True(!a.MatchesOwnedPairsPlan(true,false),"Mutated area matched reservation.");TestRunner.Equal(loads,a.AdmittedNativeLoadRequests,"Refusal changed load count.");TestRunner.Equal(writes,a.AdmittedNativeWriteRequests,"Refusal changed write count.");});
   // Owner-seed two-pair exploration: static selection, native authority and the pure setup plan/ledger.
   t.Run("owner-seed exploration admitted with one immutable load and zero writes",()=>{var f=OwnerSeed();Valid(f.Request);TestRunner.Equal("chunk7-two-pair-exploration",f.Request.SelectedChunk7Scenario,"Owner seed selected another runtime scenario.");var a=f.Scope();TestRunner.True(a.MatchesOwnedPairsPlan(false,true)&&a.MatchesOwnedPairsPlan(true,false),"Owner-seed zero-write plan missing.");Refuses(()=>f.Reserve(a));TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Load,f.Root)==null,"Sole owner-seed load refused.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Load,f.Root)!=null,"Second owner-seed load admitted.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,f.Write(1),f.Root)!=null,"Owner-seed native write admitted.");Unreserved(a);});
   t.Run("owner-seed exploration without assistance admitted",()=>{var f=OwnerSeed();f.Request.OwnedPairs.XpAssistance=null;Valid(f.Request);});
   foreach(var mutation in new[]{"rider-not-in-party","rider-a-equals-b","xp-other-unit","xp-rider-a","xp-over-ceiling","xp-under-floor","producer-run","producer-artifact","producer-archive","checkpoint-parent","pre-granted-pet","source-area","checkpoint","write1","load2","base-off","seed-hash","seed-id","run-alias","party-small","producer-input-name","seed-sha-differs","protected-campaign"})t.Run("owner-seed request refuses "+mutation,()=>{var f=OwnerSeed();var s=f.Request.OwnedPairs;switch(mutation){case "rider-not-in-party":s.PartyIds=s.PartyIds.Where(x=>x!=s.RiderBId).ToArray();break;case "rider-a-equals-b":s.RiderBId=s.RiderAId;s.XpAssistance.UnitId=s.RiderAId;break;case "xp-other-unit":s.XpAssistance.UnitId=s.PartyIds[3];break;case "xp-rider-a":s.XpAssistance.UnitId=s.RiderAId;break;case "xp-over-ceiling":s.XpAssistance.TargetCharacterLevel=9;break;case "xp-under-floor":s.XpAssistance.TargetCharacterLevel=1;break;case "producer-run":s.SourceRunId="completed-two-owner-manual";break;case "producer-artifact":s.SourceArtifactSha256=new string('c',64);break;case "producer-archive":s.SourceArchiveSha256=new string('d',64);break;case "checkpoint-parent":s.CheckpointSourceRunId="completed";break;case "pre-granted-pet":s.MountAId="55555555-1111-4111-8111-111111111111";break;case "source-area":s.SourceArea=Area;break;case "checkpoint":f.Request.PersistenceCase="multi-exploration-manual";break;case "write1":s.ExpectedNativeWriteCount=1;break;case "load2":s.ExpectedNativeLoadCount=2;break;case "base-off":s.BaseGameOnly=false;break;case "seed-hash":s.SeedSha256="D"+new string('d',63);break;case "seed-id":s.SeedId="../seed";break;case "run-alias":s.SeedId=f.Request.RunId;break;case "party-small":s.PartyIds=new[]{s.RiderAId};break;case "producer-input-name":f.Request.PersistenceLoad.FileName="Manual_9_KMC_C7_ASSISTED_FIXTURE.zks";f.Request.PersistenceLoad.InternalName="KMC_C7_ASSISTED_FIXTURE";break;case "seed-sha-differs":s.SeedSha256=new string('e',64);break;case "protecte