   foreach(var fault in new[]{"rider-a-ineligible","excess-target","short-target","missing-assistance","assistance-when-eligible","wrong-unit","rate","over-ceiling"})t.Run("owner-seed plan refuses assistance "+fault,()=>{var f=OwnerSeed();var a=RiderA();var b=RiderB();var s=f.Request.OwnedPairs;switch(fault){case "rider-a-ineligible":a.Experience=5000;a.ReadyLevel=3;break;case "excess-target":s.XpAssistance.TargetCharacterLevel=8;b.CharacterLevel=3;b.ReadyLevel=3;break;case "short-target":s.XpAssistance.TargetCharacterLevel=7;break;case "missing-assistance":s.XpAssistance=null;break;case "assistance-when-eligible":b.RangerLevel=4;b.CharacterLevel=4;break;case "wrong-unit":s.XpAssistance.UnitId=s.RiderAId;break;case "rate":b.ExperienceRate=150;break;case "over-ceiling":b.CharacterLevel=6;b.ReadyLevel=6;s.XpAssistance.TargetCharacterLevel=10;break;}TestRunner.True(Chunk7OwnerSeedSetupPlan.AssistanceErrors(s,a,b).Count>0,"Owner-seed assistance plan admitted "+fault);});
